//! Config module for `docs-live-rs`: configuration loading and router construction.

use std::fmt;
use std::path::Path;

use serde::{Deserialize, Serialize};

/// Application configuration, loaded from a JSON file.

// src/lib.rs
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct Config {
    pub name: String,
    pub port: u16,
    #[serde(rename = "adminEmail")]
    pub admin_email: String,
}

/// Errors that can occur while loading configuration.

// src/lib.rs
impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

// src/main.rs
#[tokio::main]
async fn main() {
    let router = docs_live_rs::build_router(Path::new("config.json"));
    let addr: SocketAddr = "127.0.0.1:8123".parse().expect("valid socket address");
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind listener");
    println!("docs-live-rs listening on http://{addr}");
    axum::serve(listener, router).await.expect("server failed");
