// src/lib.rs
pub fn load_config(path: &Path) -> Result<Config, ConfigError> {
    let raw = std::fs::read_to_string(path).map_err(|e| ConfigError {
        message: format!("failed to read config file: {e}"),
    })?;
    serde_json::from_str(&raw).map_err(|e| ConfigError {
        message: format!("failed to parse config JSON: {e}"),
    })
}

/// Build the application router from the configuration file at `path`
/// (internally calls [`load_config`]).
///
/// The path is stored in router state and the config is reloaded on every
/// `GET /config` request; a read or parse failure yields HTTP 400 with a
/// JSON error body.

// src/lib.rs
async fn config_handler(
    axum::extract::State(path): axum::extract::State<std::sync::Arc<std::path::PathBuf>>,
) -> (axum::http::StatusCode, axum::Json<serde_json::Value>) {
    match load_config(path.as_ref()) {
        Ok(config) => (
            axum::http::StatusCode::OK,
            axum::Json(serde_json::to_value(config).expect("Config is Serialize")),
        ),
        Err(err) => (
            axum::http::StatusCode::BAD_REQUEST,
            axum::Json(serde_json::json!({ "error": err.message })),
        ),
    }
}

